          v-for="project in projects" 
          :key="project.id" 
          class="project-card"
        >
          <div class="project-image">
            <img 
              :src="(project.images && project.images.length > 0) ? project.images[0] : project.image" 
              :alt="project.title"
              v-if="project.image || (project.images && project.images.length > 0)"
              @error="handleImageError"
            />
            <div v-else class="image-placeholder">
              <i class="fas fa-laptop-code"></i>
              <span>{{ project.title }}</span>
            </div>
            <div class="project-overlay">
              <div class="project-links">
                <a 
                  v-if="project.demoUrl" 
                  :href="project.demoUrl" 
                  target="_blank" 
                  class="project-link demo"
                >
                  <i class="fas fa-external-link-alt"></i>
                  Voir le projet
                </a>
                <a 
                  v-if="project.githubUrl"
                  :href="project.githubUrl" 
                  target="_blank" 
                  class="project-link github"
                >
                  <i class="fab fa-github"></i>
                  Code source
                </a>
              </div>
            </div>
          </div>
          
          <div class="project-content">
            <div class="project-category">{{ project.category }}</div>
            <h3 class="project-title">{{ project.title }}</h3>
            <p class="project-description">{{ project.description }}</p>
            
            <div class="project-technologies">
              <span 
                v-for="tech in project.technologies" 
                :key="tech" 
                class="tech-tag"
              >
                {{ tech }}
              </span>
            </div>
            
            <div class="project-actions">
              <button 
                @click="openProjectModal(project)"
                class="btn-more"
              >
                <i class="fas fa-info-circle"></i>
                Plus de détails
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div v-if="selectedProject" class="modal-overlay" @click="closeModal">
      <div class="modal-content" @click.stop>
        <button class="modal-close" @click="closeModal">
          <i class="fas fa-times"></i>
        </button>
        
        <div class="modal-body">
          <div class="modal-image-container">
            <div v-if="selectedProject.images && selectedProject.images.length > 0" class="image-slider">
              <img 
                :src="selectedProject.images[currentImageIndex]" 
                :alt="selectedProject.title" 
                class="slider-image"
              />
              
              <div v-if="selectedProject.images.length > 1" class="slider-controls">
                <button @click="prevImage" class="slider-btn prev-btn">
                  <i class="fas fa-chevron-left"></i>
                </button>
                <button @click="nextImage" class="slider-btn next-btn">
                  <i class="fas fa-chevron-right"></i>
                </button>
              </div>
              
              <div v-if="selectedProject.images.length > 1" class="slider-dots">
                <span 
                  v-for="(img, index) in selectedProject.images" 
                  :key="index"
                  :class="['dot', { active: index === currentImageIndex }]"
                  @click="setCurrentImage(index)"
                ></span>
              </div>
            </div>
            
            <div v-else-if="selectedProject.image" class="image-single">
              <img :src="selectedProject.image" :alt="selectedProject.title" />
            </div>
            
            <div v-else class="image-placeholder">
              <i class="fas fa-laptop-code"></i>
              <span>{{ selectedProject.title }}</span>
            </div>
          </div>
          
          <div class="modal-details">
            <div class="modal-category">{{ selectedProject.category }}</div>
            <h2 class="modal-title">{{ selectedProject.title }}</h2>
            <p class="modal-full-description">{{ selectedProject.fullDescription }}</p>
            
            <div class="modal-technologies">
              <h4>Technologies utilisées :</h4>
              <div class="tech-list">
                <span 
                  v-for="tech in selectedProject.technologies" 
                  :key="tech" 
                  class="tech-tag large"
                >
                  {{ tech }}
                </span>
              </div>
            </div>
            
            <div class="modal-links">
