          demoUrl: null,
          githubUrl: 'https://github.com/sofiastron/AgoraCampus/tree/etudiant'
        }
      ]
    }
  },
  methods: {
    handleImageError(event) {
      const parent = event.target.parentElement;
      parent.innerHTML = `
        <div class="image-placeholder">
          <i class="fas fa-laptop-code"></i>
          <span>Image du projet</span>
        </div>
      `;
    },
    openProjectModal(project) {
      this.selectedProject = project;
      this.currentImageIndex = 0; 
      document.body.style.overflow = 'hidden';
    },
    closeModal() {
      this.selectedProject = null;
      document.body.style.overflow = 'auto';
    },
    nextImage() {
      if (this.currentImageIndex < this.selectedProject.images.length - 1) {
        this.currentImageIndex++;
      } else {
        this.currentImageIndex = 0; 
      }
    },
    prevImage() {
      if (this.currentImageIndex > 0) {
        this.currentImageIndex--;
      } else {
        this.currentImageIndex = this.selectedProject.images.length - 1; 
      }
    },
    setCurrentImage(index) {
      this.currentImageIndex = index;
    }
  }
}
</script>

