            'Utilisation d\'outils IA pour Microsoft 365 et l\'automatisation de tâches',
            'Réflexion sur l\'impact de l\'IA sur le travail et l\'apprentissage'
          ]
        },
        {
          title: 'Java (Basic) Certification',
          issuer: 'HackerRank',
          date: '2026',
          description: 'Certification attestant des compétences fondamentales en programmation Java.',
          category: 'Développement Logiciel',
          status: 'completed',
          icon: 'fab fa-java',
          skills: [
            'Java Fundamentals',
            'Object-Oriented Programming',
            'Data Types & Control Flow',
            'Problem Solving'
          ],
          credentialUrl: 'https://www.hackerrank.com/certificates/iframe/ec1c18d095b7',
          details: [
