  from {
    opacity: 0;
  }
  to {
    opacity: 0.8;
  }
}

.certifications-filters {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 3rem;
  animation: fadeIn 1s ease 0.4s both;
}

.filter-btn {
  padding: 0.8rem 1.5rem;
  border: 2px solid var(--secondary-color);
  background: transparent;
  color: var(--secondary-color);
  border-radius: 25px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-weight: 500;
  font-size: 0.9rem;
}

.filter-btn.active,
.filter-btn:hover {
  background: var(--secondary-color);
  color: white;
  transform: translateY(-2px) scale(1.05);
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

.certifications-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(420px, 1fr));
  gap: 3rem;
  margin-bottom: 4rem;
}

.certification-card {
  background: var(--white);
  border-radius: 20px;
  padding: 2.5rem;
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  border-left: 5px solid var(--secondary-color);
  position: relative;
  overflow: hidden;
  animation: fadeInUp 0.6s ease both;
  animation-delay: calc(var(--card-index, 0) * 0.1s);
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.certification-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(52, 152, 219, 0.05), rgba(41, 128, 185, 0.05));
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.certification-card:hover::before {
  opacity: 1;
}

.certification-card:hover {
  transform: translateY(-10px) scale(1.02);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
}

.certification-card.completed {
  border-left-color: #27ae60;
}

.certification-card.in-progress {
  border-left-color: #f39c12;
}

.certification-card.planned {
  border-left-color: #95a5a6;
}

.certification-header {
  display: flex;
  align-items: flex-start;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

.certification-badge {
  width: 70px;
  height: 70px;
  background: linear-gradient(135deg, var(--secondary-color), #3498db);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.8rem;
  flex-shrink: 0;
  transition: all 0.3s ease;
  box-shadow: 0 5px 15px rgba(52, 152, 219, 0.3);
}

.certification-card:hover .certification-badge {
  transform: rotate(360deg) scale(1.1);
  box-shadow: 0 8px 20px rgba(52, 152, 219, 0.5);
}

.certification-card.completed .certification-badge {
  background: linear-gradient(135deg, #27ae60, #2ecc71);
}

.certification-card.in-progress .certification-badge {
  background: linear-gradient(135deg, #f39c12, #f1c40f);
}

.certification-card.planned .certification-badge {
  background: linear-gradient(135deg, #95a5a6, #bdc3c7);
}

.certification-info h3 {
  color: var(--primary-color);
  font-size: 1.4rem;
  margin-bottom: 0.5rem;
  line-height: 1.3;
  transition: color 0.3s ease;
}

.certification-card:hover .certification-info h3 {
  color: var(--secondary-color);
}

.cert-issuer {
