    text-align: center;
    gap: 1rem;
  }
  
  .certification-footer {
    flex-direction: column;
    gap: 1rem;
    align-items: stretch;
  }
  
  .cert-actions {
    justify-content: center;
  }
  
  .certifications-stats {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
  }
  
  .stat {
    padding: 1.5rem 1rem;
  }
}

@media (max-width: 480px) {
  .certifications-filters {
    gap: 0.5rem;
  }
  
  .filter-btn {
    padding: 0.6rem 1rem;
    font-size: 0.8rem;
  }
  
  .certifications-grid {
    grid-template-columns: 1fr;
  }
  
  .certifications-stats {
    grid-template-columns: 1fr;
  }
  
  .cert-actions {
    flex-direction: column;
    gap: 0.5rem;
  }
  
  .btn-view,
  .btn-details {
    width: 100%;
    text-align: center;
  }

  .certification-badge {
    width: 60px;
    height: 60px;
    font-size: 1.5rem;
  }

